def gen(idx, path, extra_comment):
    out = ['<?xml version="1.0" encoding="utf-8"?>', f'<!-- Generated by apps/android/tools/strings.py ({extra_comment}) — edit the table there. -->', '<resources>']
    for k, v in S.items():
        t = v[idx]
        t = escape(t).replace("'", "\\'").replace('"', '\\"')
        t = re.sub(r'%(?!\d\$[sd])', '%%', t)
        out.append(f'    <string name="{k}">{t}</string>')
    out.append('</resources>')
    os.makedirs(os.path.dirname(path), exist_ok=True)
    open(path, 'w', encoding='utf-8').write("\n".join(out) + "\n")

here = os.path.dirname(os.path.abspath(__file__))
res = os.path.join(here, "../app/src/main/res")
gen(0, os.path.join(res, "values/strings.xml"), "Turkish, primary")
gen(1, os.path.join(res, "values-en/strings.xml"), "English")
print(len(S), "strings")
